public class MainActivity extends Activity{
 static final String VERSION="v1.3-test-fields";
 static final String PREF="gt7_test_fields_v13";
 static final String URL_KEY="bridge_url";
 static final String DEFAULT_URL="http://192.168.1.70:8787";
 Handler handler=new Handler(Looper.getMainLooper());
 DataView view; JSONObject data=new JSONObject(); String bridgeUrl; boolean running=false;
 Runnable loop=new Runnable(){public void run(){loadTelemetry();handler.postDelayed(this,500);}};

 public void onCreate(Bundle b){
  super.onCreate(b);
  requestWindowFeature(Window.FEATURE_NO_TITLE);
  getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);
  getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
  bridgeUrl=getSharedPreferences(PREF,0).getString(URL_KEY,DEFAULT_URL);
  view=new DataView(this);
  setContentView(view);
  start();
 }
 protected void onResume(){super.onResume();start();}
 protected void onPause(){super.onPause();stop();}
 void start(){if(!running){running=true;handler.post(loop);}}
 void stop(){running=false;handler.removeCallbacks(loop);}
 void loadTelemetry(){new Thread(()->{try{String body=http(bridgeUrl+"/api/fields");if(body==null||body.trim().length()==0)body=http(bridgeUrl+"/api/telemetry");data=flatten(body);}catch(Exception e){try{data.put("__status","OFFLINE");}catch(Exception ignored){}}runOnUiThread(()->view.invalidate());}).start();}
 String http(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(900);c.setReadTimeout(900);BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder sb=new StringBuilder();String line;while((line=br.readLine())!=null)sb.append(line);br.close();c.disconnect();return sb.toString();}
 JSONObject flatten(String body)throws Exception{JSONObject out=new JSONObject();String s=body.trim();int a=s.indexOf('{'),b=s.lastIndexOf('}');Object root=new JSONTokener(a>=0&&b>a?s.substring(a,b+1):s).nextValue();flat(out,"",root);return out;}
 void flat(JSONObject out,String prefix,Object obj)throws Exception{if(obj instanceof JSONObject){JSONObject o=(JSONObject)obj;Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next();Object v=o.get(k);String p=prefix.length()==0?k:prefix+"."+k;flat(out,p,v);if(v instanceof JSONObject && (k.equals("fields")||k.equals("telemetry")||k.equals("position")))flat(out,"",v);}}else if(obj instanceof JSONArray){JSONArray a=(JSONArray)obj;for(int i=0;i<a.length();i++)flat(out,prefix+"."+i,a.get(i));}else out.put(prefix,String.valueOf(obj));}
 void bridgeDialog(){android.widget.EditText input=new android.widget.EditText(this);input.setText(bridgeUrl);new AlertDialog.Builder(this).setTitle("Bridge URL").setView(input).setPositiveButton("Salvar",(d,w)->{bridgeUrl=input.getText().toString().trim();if(!bridgeUrl.startsWith("http"))bridgeUrl="http://"+bridgeUrl;getSharedPreferences(PREF,0).edit().putString(URL_KEY,bridgeUrl).apply();}).setNegativeButton("Cancelar",null).show();}

 class DataView extends View{
  Paint p=new Paint(Paint.ANTI_ALIAS_FLAG); RectF r=new RectF(); float scale=1,scroll=0,lastY=0; ArrayList<Field> fields=new ArrayList<>();
  DataView(Activity a){super(a);setBackgroundColor(Color.BLACK);buildFields();}
  void buildFields(){add("Status","__status");add("Speed km/h","speed_kmh","speedKmh","velocityKmh","velocidade","kmh","speed");add("Speed m/s","speed_ms","speedMS","speed_mps","speedMps");add("RPM","rpm","EngineRPM","engineRPM","engine_rpm","currentRpm");add("Gear","gear","currentGear","marcha","gears");add("Suggested Gear","suggestedGear","suggested_gear");add("Throttle","throttle","throttleFiltered","throttle_percent","acelerador");add("Brake","brake","brakeFiltered","brake_percent","freio");add("Steering","steering","steer","wheelSteeringAngle","wheelSteeringAngle.0","anguloVolante");add("Fuel Level L","fuelLevel","fuel","fuelLiters","fuel_liters");add("Fuel Capacity","fuelCapacity","fuel_capacity","tank_capacity");add("Fuel Percent","fuelPercent","fuel_percent","combustivelPorcentagem");add("Boost","boost","turbo","boostPressure","turbo_pressure");add("Oil Pressure","oilPressure","oil_pressure");add("Water Temp","waterTemp","coolantTemp","water_temp","temperaturaAgua");add("Oil Temp","oilTemp","oil_temp");add("Tyre Temp FL","tyreTempFL","tireTempFL","tyreTemp.0","tyreTemp[0]","tire_fl");add("Tyre Temp FR","tyreTempFR","tireTempFR","tyreTemp.1","tire_fr");add("Tyre Temp RL","tyreTempRL","tireTempRL","tyreTemp.2","tire_rl");add("Tyre Temp RR","tyreTempRR","tireTempRR","tyreTemp.3","tire_rr");add("Wheel RPS FL","wheelRPSFL","wheelRpsFL","wheelRPS.0","wheel_rps_fl");add("Wheel RPS FR","wheelRPSFR","wheelRpsFR","wheelRPS.1","wheel_rps_fr");add("Wheel RPS RL","wheelRPSRL","wheelRpsRL","wheelRPS.2","wheel_rps_rl");add("Wheel RPS RR","wheelRPSRR","wheelRpsRR","wheelRPS.3","wheel_rps_rr");add("Tyre Radius FL","tyreRadiusFL","tyreRadius.0");add("Tyre Radius FR","tyreRadiusFR","tyreRadius.1");add("Susp Height FL","suspHeightFL","suspensionFL","suspHeight.0","susp_fl");add("Susp Height FR","suspHeightFR","suspensionFR","suspHeight.1","susp_fr");add("Susp Height RL","suspHeightRL","suspensionRL","suspHeight.2","susp_rl");add("Susp Height RR","suspHeightRR","suspensionRR","suspHeight.3","susp_rr");add("Lap Count","lapCount","lap","currentLap","completed_laps","voltasCorrigidas");add("Total Laps","totalLaps","raceTotalLaps");add("Best Lap","bestLaptime","bestLap","best_lap","best_lap_text","melhorVolta");add("Last Lap","lastLaptime","lastLap","last_lap","last_lap_text","ultimaVolta");add("Current Lap Time","currentLapTime","current_lap_text");add("Day Progression","dayProgression");add("Race Start Position","RaceStartPosition","raceStartPosition");add("Pre Race Num Cars","preRaceNumCars");add("Min Alert RPM","minAlertRPM","min_alert_rpm");add("Max Alert RPM","maxAlertRPM","max_alert_rpm");add("Calc Max Speed","calcMaxSpeed","calculatedMaxSpeed","maxSpeed");add("Flags","flags","SimulatorFlags");add("Car On Track","CarOnTrack","carOnTrack");add("Paused","Paused","paused");add("Loading","LoadingOrProcessing","loading");add("In Gear","InGear","inGear");add("Has Turbo","HasTurbo","hasTurbo");add("Rev Limiter Alert","RevLimiterBlinkAlertActive","revLimiterBlinkAlertActive");add("Hand Brake","HandBrakeActive","handBrakeActive");add("Lights","LightsActive","lightsActive");add("High Beam","HighBeamActive","highBeamActive");add("Low Beam","LowBeamActive","lowBeamActive");add("ASM Active","ASMActive","asmActive");add("TCS Active","TCSActive","tcsActive");add("Position X","position.x","positionX","posX","x");add("Position Y","position.y","positionY","posY","y");add("Position Z","position.z","positionZ","posZ","z");add("Velocity X","worldVelocity.0","velocityX","velX");add("Velocity Y","worldVelocity.1","velocityY","velY");add("Velocity Z","worldVelocity.2","velocityZ","velZ");add("Rotation Pitch","rotation.0","pitch","rotationPitch");add("Rotation Yaw","rotation.1","yaw","rotationYaw");add("Rotation Roll","rotation.2","roll","rotationRoll");add("Orientation North","orientationRelativeToNorth","orientation");add("Angular Vel X","angularVelocity.0","angularVelocityX");add("Angular Vel Y","angularVelocity.1","angularVelocityY");add("Angular Vel Z","angularVelocity.2","angularVelocityZ");add("Body Height","bodyHeight");add("Road Plane X","roadPlane.0","roadPlaneX");add("Road Plane Y","roadPlane.1","roadPlaneY");add("Road Plane Z","roadPlane.2","roadPlaneZ");add("Road Plane Distance","roadPlaneDistance");add("Clutch","clutch");add("Clutch Engagement","clutchEngagement");add("RPM Clutch Gearbox","RPMFromClutchToGearbox","rpmFromClutchToGearbox");add("Transmission Top Speed","transmissionTopSpeed");for(int i=0;i<8;i++)add("Gear Ratio "+(i+1),"gearRatios."+i,"gearRatio"+(i+1));add("Car Code","carCode","car_code","codigoCarro");add("Wheel Rotation","wheelRotation");add("Steering Angular Vel","steeringAngularVelocity");add("Sway Accel","sway","gForceLat","g_lat","lateralG");add("Heave Accel","heave","gForceVert","g_vertical","verticalG");add("Surge Accel","surge","gForceLong","g_long","longitudinalG");add("Energy Recovery","energyRecovery");for(int i=0;i<4;i++)add("Torque Vector "+(i+1),"torqueVectors."+i);add("Surface FL","surfaceType.0","surfaceFL");add("Surface FR","surfaceType.1","surfaceFR");add("Surface RL","surfaceType.2","surfaceRL");add("Surface RR","surfaceType.3","surfaceRR");add("Current Lap ms","currentLap");add("Wheel Steering L","wheelSteeringAngle.0");add("Wheel Steering R","wheelSteeringAngle.1");add("Wheel Base","wheelBase");add("Car Category","carCategory");add("Track Name","trackName","track","pista","circuit");add("Car Name","carName","car","modelo");add("Raw Packet ID","packetId","packet_id");}
  void add(String name,String...keys){fields.add(new Field(name,keys));}
  protected void onDraw(Canvas c){scale=getWidth()/430f;c.save();c.scale(scale,scale);draw(c,430,getHeight()/scale);c.restore();}
  void draw(Canvas c,float w,float h){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(0,5,10));c.drawRect(0,0,w,h,p);txt(c,"GT7 TELEMETRY FIELD TEST",14,28,16,Color.WHITE,1,Paint.Align.LEFT);txt(c,VERSION+"  toque na lixeira para ocultar",14,45,9,Color.rgb(80,190,255),0,Paint.Align.LEFT);txt(c,"BRIDGE",w-20,28,10,Color.rgb(255,80,100),1,Paint.Align.RIGHT);c.save();c.translate(0,-scroll);float y=64;int shown=0,working=0;for(int i=0;i<fields.size();i++){Field f=fields.get(i);if(hidden(i))continue;String val=value(f);if(!val.equals("--"))working++;row(c,i,y,f.name,val);y+=44;shown++;}c.restore();p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(0,5,10));c.drawRect(0,h-32,w,h,p);txt(c,"visiveis "+shown+"   funcionando "+working+"   total "+fields.size(),14,h-12,10,Color.WHITE,0,Paint.Align.LEFT);}
  void row(Canvas c,int index,float y,String name,String val){boolean ok=!val.equals("--");r.set(10,y,420,y+38);p.setStyle(Paint.Style.FILL);p.setColor(ok?Color.rgb(3,24,20):Color.rgb(12,16,22));c.drawRoundRect(r,8,8,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(ok?Color.rgb(0,130,90):Color.rgb(45,70,90));c.drawRoundRect(r,8,8,p);txt(c,name,20,y+16,10,Color.rgb(180,215,235),0,Paint.Align.LEFT);txt(c,val,20,y+32,12,ok?Color.WHITE:Color.rgb(100,120,130),1,Paint.Align.LEFT);txt(c,"🗑",398,y+25,17,Color.rgb(255,75,95),1,Paint.Align.CENTER);}
  String value(Field f){try{for(String k:f.keys){if(data.has(k)&&!data.isNull(k)){String v=String.valueOf(data.get(k));if(v.length()>0&&!v.equals("null"))return v;}}}catch(Exception e){}return "--";}
  boolean hidden(int i){return getSharedPreferences(PREF,0).getBoolean("hide_"+i,false);}
  public boolean onTouchEvent(MotionEvent e){float x=e.getX()/scale,y=e.getY()/scale;if(e.getAction()==MotionEvent.ACTION_DOWN){lastY=y;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){scroll=Math.max(0,scroll-(y-lastY));lastY=y;invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(y<52&&x>330){bridgeDialog();return true;}int row=(int)((y+scroll-64)/44);if(row>=0){int real=-1,count=-1;for(int i=0;i<fields.size();i++){if(hidden(i))continue;count++;if(count==row){real=i;break;}}if(real>=0&&x>365){getSharedPreferences(PREF,0).edit().putBoolean("hide_"+real,true).apply();invalidate();return true;}}}return true;}
  void txt(Canvas c,String s,float x,float y,float sz,int col,int bold,Paint.Align a){p.setStyle(Paint.Style.FILL);p.setColor(col);p.setTextSize(sz);p.setTextAlign(a);p.setTypeface(bold==1?Typeface.create(Typeface.SANS_SERIF,Typeface.BOLD):Typeface.create(Typeface.SANS_SERIF,Typeface.NORMAL));c.drawText(s==null?"--":s,x,y,p);}
 }
 static class Field{String name;String[] keys;Field(String n,String[] k){name=n;keys=k;}}
}
